TLM.f("Commune/C3a",{"officium":"Commune Plurimorum Martyrum: Sapientiam Sanctorum","rule":[],"sections":{"Introitus":[{"k":"ref","la":"Eccli 44:15; 44:14"},{"k":"text","la":"Sapiéntiam Sanctórum narrent populi, et laudes eórum núntiet ecclésia: nómina autem eórum vivent in sǽculum sǽculi."},{"k":"ref","la":"Ps 32:1"},{"k":"text","la":"Exsultáte, justi, in Dómino: rectos decet collaudátio."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Sapiéntiam Sanctórum narrent populi, et laudes eórum núntiet ecclésia: nómina autem eórum vivent in sǽculum sǽculi."}],"Oratio":[{"k":"text","la":"Deus, qui nos concédis sanctórum Mártyrum tuórum N. et N. natalítia cólere: da nobis in ætérna beatitúdine de eórum societáte gaudére."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Lectio libri Sapientiæ"},{"k":"ref","la":"Sap 5:16-20"},{"k":"text","la":"Justi autem in perpétuum vivent, et apud Dóminum est merces eórum, et cogitátio illórum apud Altíssimum. Ideo accípient regnum decóris, et diadéma speciéi de manu Dómini: quóniam déxtera sua teget eos, et bráchio sancto suo deféndet illos. Accípiet armatúram zelus illíus, et armábit creatúram ad ultiónem inimicórum. Induet pro thoráce justítiam, et accípiet pro gálea judícium certum. Sumet scutum inexpugnábile æquitátem."}],"Graduale":[{"k":"ref","la":"Ps 123:7-8"},{"k":"text","la":"Anima nostra, sicut passer, erépta est de láqueo venántium."},{"k":"text","la":"Láqueus contrítus est, et nos liberáti sumus: adjutórium nostrum in nómine Dómini, qui fecit cœlum et terram. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Ps 67:4"},{"k":"text","la":"Justi epuléntur, et exsúltent in conspéctu Dei: et delecténtur in lætítia. Alleluja."}],"Tractus":[{"k":"ref","la":"Ps 123:7-8"},{"k":"text","la":"Anima nostra, sicut passer, erépta est de láqueo venántium."},{"k":"text","la":"Láqueus contrítus est, et nos liberáti sumus: adjutórium nostrum in nómine Dómini, qui fecit cœlum et terram.","mark":"V"},{"k":"ref","la":"Ps 125:5-6"},{"k":"text","la":"Qui séminant in lácrimis, in gáudio metent."},{"k":"text","la":"Eúntes ibant et flebant, mitténtes sémina sua.","mark":"V"},{"k":"text","la":"Veniéntes autem vénient cum exsultatióne, portántes manípulos suos.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 6:17-23"},{"k":"text","la":"In illo témpore: Descéndens Jesus de monte, stetit in loco campéstri, et turba discipulórum ejus, et multitúdo copiósa plebis ab omni Judǽa, et Jerúsalem, et marítima, et Tyri, et Sidónis, qui venérant, ut audírent eum et sanaréntur a languóribus suis. Et, qui vexabántur a spirítibus immúndis, curabántur. Et omnis turba quærébat eum tángere: quia virtus de illo exíbat, et sanábat omnes. Et ipse, elevátis oculis in discípulos suos, dicébat: Beáti, páuperes: quia vestrum est regnum Dei. Beáti, qui nunc esurítis: quia saturabímini. Beáti, qui nunc fletis: quia ridébitis. Beáti éritis, cum vos óderint hómines, et cum separáverint vos et exprobréverint, et ejécerint nomen vestrum tamquam malum, propter Fílium hóminis. Gaudéte in illa die et exsultáte: ecce enim, merces vestra multa est in cœlo."}],"Offertorium":[{"k":"ref","la":"Ps 149:5-6"},{"k":"text","la":"Exsultábunt Sancti in glória, lætabúntur in cubílibus suis: exaltatiónes Dei in fáucibus eórum, allelúja."}],"Secreta":[{"k":"text","la":"Múnera tibi, Dómine, nostra devotiónis offérimus: quæ et pro tuórum tibi grata sint honóre Justórum, et nobis salutária, te miseránte, reddántur."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Luc 12:4"},{"k":"text","la":"Dico autem vobis amícis meis: Ne terreámini ab his, qui vos persequúntur."}],"Postcommunio":[{"k":"text","la":"Præsta nobis, quǽsumus, Dómine: intercedéntibus sanctis Martýribus tuis N. et N.; ut, quod ore contíngimus, pura mente capiámus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"81e853df7532e872":{"t":"Sir 44, 15 i 14, Ps 32, 1\n(Sir 44, 15 i 14) O mudrosti svetih neka pripovijedaju narodi, a Crkva neka naviješta hvalu njihovu. Njihova imena žive kroz vjekove. (Ps 32, 1) Radujte se, pravednici, u Gospodinu, pravednicima dolikuje da ga hvale.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Sir 44, 15 i 14) O mudrosti svetih neka pripovijedaju narodi, a Crkva neka naviješta hvalu njihovu. Njihova imena žive kroz vjekove.","kn":"(Crkv. 44, 15, 14). Mudrost svetih neka pripovijedaju naroidi i Crkva neka oglasuje slavu njihovu; imena će njihova živjeti u vjekovječne vjekove.’ (Ps 32, 1) Radujte se, pravednici, u Gospodinu; slavite Gospodina s pjesmom! Slava Ocu... Mudrost . . .","knRef":"Kniewald 1942, str. 798–799 (snimka 400) (OCR)"},"37e1e202606df068":{"kn":"Bože, koji dopuštaš, da slavimo rođeni dan svetih I. i I., Tvojih mučenika, podaj, da u vječnom blaženstvu uživamo njihovo društvo.\n<i>Po G. n.</i>","knRef":"Kniewald 1942, str. 800"},"79e56af343e4528e":{"t":"Mudr 5, 16-20\nČitanje knjige Mudrosti. Pravednici će vječno živjeti. U Gospodinu je njihova plaća i Svevišnji se brine za njih. Od Gospodina će dobiti divno kraljevstvo i krasan vijenac, jer će ih on zakriliti svojom desnicom i obraniti svojom snagom. U svojoj će se revnosti prihvatiti oružja i naoružat će svoje, da bi se osvetio neprijateljima. Pravednost će obući kao oklop, a stalna pravda bit će mu kao kaciga i pokrit će se pravednošću kao neprobojnim štitom.","kn":"Čitanje Knjige mudrosti (5, 16-20). Pravednici će vječno živjeti i u Gospodina je njihova plaća i za njih se brine Svevišnji. Zato će od Gospodina dobiti kraljevsko odličje i divan vijenac, jer će ih ziikriliti svo-jom desnicom i obraniti svojom svetom mišicom. U svojoj će revnosti prihvatiti za oružje i svoje će naoružati, da se osveti neprijateljima. Odjenut će pravednost kao oklop i za kacigu do-bit će tvrdu pravdu i pokrit će se pravednošću kao nesavladivim štitom.","knRef":"Kniewald 1942, str. 800–801 (snimka 401) (OCR)"},"fb42182204a45745":{"kn":"(Ps. 123, 7-8). Izbjegli smo kao ptice iz zamke. Zamka se rastrgla, mi smo slobodni! Pomoć je naša u imenu Gospodina, koji stvori nebo i zemlju!\nAleluja, aleluja! (Ps. 67, 4) Pravednici neka radosno blaguju pred licem Božjim, neka se raduju i vesele. Aleluja!","knRef":"Kniewald 1942, str. 800"},"67f4feac8d3daae0":{"t":"Lk 6, 17-23\nSlijedi sveto Evanđelje po Luki. U ono vrijeme siđe Isus s gore, zaustavi se na ravnici s mnoštvom svojih učenika i vrlo mnogo ljudi iz čitave Judeje, Jeruzalema, Primorja, Tira i Sidona, koji su došli da ga čuju i da se izliječe od svojih bolesti. I ozdravljali su oni koje su mučili nečisti duhovi. I sav ga se svijet htio dotaknuti, jer je iz njega izlazila moć, i sve je liječio. On podigne oči prema svojim učenicima i reče: Blago vama siromasima, jer je vaše Božje kraljevstvo. Blago vama koji sada gladujete, jer ćete se nasititi. Blago vama kada vas ljudi mrze i odbace, pogrde i prezru kao nečasne radi Sina Čovječjega. Radujte se i veselite u taj dan, jer je velika vaša plaća na nebu!","kn":"t Slijedi sveto evanđelje po Luki (6, 17-23). U ono vrijeme siđe Isus s gore, zaustavi se na ravnici s četom svojih učenika i vrlo mnogo ljudi iz sve Judeje i Jeruzalema i primorja i Tira i Sidona, koji su došli da ga čuju i liječe se od svojih bolesti. I ozdravljali su oni, koje su mučili nečisti duhovi. I sav je svijet htio da ga se dotakne, jer je iz njega Izlazila moć i liječio je sve. A o.n podigne^ oči na svoje učenike i reče: Blago vama siromasima, jer je vaše kraljevstvo nebesko. Blago vama, koji sada gladujete, jer ćete se nasltiti. Blago vama, koji sada plačete, jer ćete se smijati. Blago vama, kad vas ljudi mrze i odbace vas, pogrde i prezru kao nečasne radi Sina čovječjega. Radujte se^ onoga dana i veselite, jer je velika vaša plaća na nebu.","knRef":"Kniewald 1942, str. 484–485 (snimka 243) (OCR)"},"31873133e7eef8f0":{"kn":"(Ps. 149, 5-6). Sveti kliču u svojoj slavi i raduju se u svom pokoju; Božje su pjesme u ustima njihovim. Aleluja.","knRef":"Kniewald 1942, str. 801"},"0b5f9e55c57d534d":{"t":"Prikazujemo ti, Gospodine, darove svoje odanosti, da ti budu mili zbog časti tvojih pravednika, a nama postanu spasonosni po tvom milosrđu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Prikazujemo Ti, Gospodine, darove naše poboznosti moleći Te, da. Tebi budu dragi poradi časti Tvojih pravednika, a nama da po Tvome milosrđu budu spasonasniji, (po G. n.","knRef":"Kniewald 1942, str. 488–489 (snimka 245) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"75db2b5c431a023c":{"kn":"(Lk. 12, 4). Kažem vam, prijatelji moji: ne bojte se onih, koji vas progone!","knRef":"Kniewald 1942, str. 801"},"95b3be2ae10b5548":{"kn":"Podaj nam, molimo, Gospodine, da zagovorom Tvojih svetih mučenika I. i I., čistom dušom prihvatimo, što ustima primamo.\n<i>po G. n.</i>","knRef":"Kniewald 1942, str. 801"}},"variants":{"paschal":{"Introitus":[{"k":"ref","la":"Ps 63:3"},{"k":"text","la":"Protexísti me, Deus, a convéntu malignántium, allelúja: a multitúdine operántium iniquitátem, allelúja, allelúja."},{"k":"ref","la":"Ps. 63:2"},{"k":"text","la":"Exáudi, Deus, oratiónem meam cum déprecor: a timóre inimíci éripe ánimam meam."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Protexísti me, Deus, a convéntu malignántium, allelúja: a multitúdine operántium iniquitátem, allelúja, allelúja."}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Sap 5:1-5"},{"k":"text","la":"Stabunt justi in magna constántia advérsus eos, qui se angustiavérunt et qui abstulérunt labóres eórum. Vidéntes turbabúntur timore horríbili, et mirabúntur in subitatióne insperátæ salútis, dicéntes intra se, poeniténtiam agéntes, et præ angústia spíritus geméntes: Hi sunt, quos habúimus aliquándo in derísum et in similitúdinem impropérii. Nos insensáti vitam illórum æstimabámus insániam, et finem illórum sine honóre: ecce, quómodo computáti sunt inter fílios Dei, et inter Sanctos sors illórum est."}],"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 88:6"},{"k":"text","la":"Confitebúntur cœli mirabília tua, Dómine: étenim veritátem tuam in ecclésia sanctórum. Allelúja."},{"k":"ref","la":"Ps 20:4"},{"k":"text","la":"Posuísti, Dómine, super caput ejus corónam de lápide pretióso. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joannes 15:1-7"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Ego sum vitis vera: et Pater meus agrícola est. Omnem pálmitem in me non feréntem fructum, tollet eum: et omnem, qui fert fructum, purgábit eum, ut fructum plus áfferat. Jam vos mundi estis propter sermónem, quem locútus sum vobis. Manéte in me: et ego in vobis. Sicut palmes non potest ferre fructum a semetípso, nisi mánserit in vite: sic nec vos, nisi in me manséritis. Ego sum vitis, vos pálmites: qui manet in me, et ego in eo, hic fert fructum multum: quia sine me nihil potéstis fácere. Si quis in me non mánserit, mittétur foras sicut palmes, et aréscet, et cólligent eum, et in ignem mittent, et ardet. Si manséritis in me, et verba mea in vobis mánserint: quodcúmque voluéritis, petétis, et fiet vobis."}],"Offertorium":[{"k":"ref","la":"Ps 88:6"},{"k":"text","la":"Confitebúntur cœli mirabília tua, Dómine: et veritátem tuam in ecclésia sanctórum, allelúja, allelúja."}],"Communio":[{"k":"ref","la":"Ps 63:11"},{"k":"text","la":"Lætábitur justus in Dómino, et sperábit in eo: et laudabúntur omnes recti corde, allelúja, allelúja."}]}}});
